-- Dados artificiais de teste; tudo é revertido no final.
begin;
select no_plan();
select has_table('public','waitlist','Lista existe');
select ok(not has_table_privilege('anon','public.waitlist','select'),'Anon não lê endereços');
select ok(not has_table_privilege('authenticated','public.consent_records','select'),'Authenticated não lê consentimentos de espera');
select ok(not has_table_privilege('anon','public.rate_limits','insert'),'Cliente não altera limite');
select ok(not has_function_privilege('anon','public.join_waitlist(text,text,inet,text)','execute'),'RPC de inscrição privada');
select ok(not has_function_privilege('authenticated','public.leave_waitlist(text,text)','execute'),'RPC de revogação privada');
select ok(has_function_privilege('service_role','public.join_waitlist(text,text,inet,text)','execute'),'Servidor tem execução específica');
select is(public.join_waitlist('fase2-sql@example.invalid',repeat('1',64),'192.168.1.0/24',repeat('a',64)),'accepted','Inscrição aceita');
select is((select count(*)::integer from public.waitlist where normalized_email='fase2-sql@example.invalid'),1,'E-mail persistido');
select is((select count(*)::integer from public.consent_records c join public.waitlist w on w.id=c.waitlist_id where w.normalized_email='fase2-sql@example.invalid'),1,'Consentimento atômico');
select is((select c.text_version from public.consent_records c join public.waitlist w on w.id=c.waitlist_id where w.normalized_email='fase2-sql@example.invalid'),'waitlist-v1-2026-10-30','Versão gravada');
select is((select c.ip_truncated::text from public.consent_records c join public.waitlist w on w.id=c.waitlist_id where w.normalized_email='fase2-sql@example.invalid'),'192.168.1.0/24','Somente IP truncado');
select is(public.join_waitlist('fase2-sql@example.invalid',repeat('1',64),'192.168.1.0/24',repeat('b',64)),'accepted','Duplicata tem mesma resposta');
select is((select unsubscribe_token_digest from public.waitlist where normalized_email='fase2-sql@example.invalid'),repeat('a',64),'Duplicata não sequestra token de cancelamento');
select is((select count(*)::integer from public.consent_records c join public.waitlist w on w.id=c.waitlist_id where w.normalized_email='fase2-sql@example.invalid'),1,'Duplicata não inventa consentimento');
select is((select count(*)::integer from generate_series(1,6) g where public.join_waitlist('fase2-rate-'||g||'@example.invalid',repeat('2',64),'2001:db8:0::/48',md5(g::text)||md5('token'||g))='accepted'),5,'Só cinco pedidos por hora');
select is(public.join_waitlist('fase2-rejected@example.invalid',repeat('2',64),'2001:db8:0::/48',repeat('c',64)),'rate_limited','Excedente limitado');
select is(public.leave_waitlist(repeat('b',64),repeat('1',64)),'accepted','Token inexistente não enumera');
select is((select count(*)::integer from public.waitlist where normalized_email='fase2-sql@example.invalid'),1,'Token inválido não cancela inscrição existente');
create temporary table consent_fixture as select id from public.waitlist where normalized_email='fase2-sql@example.invalid';
select is(public.leave_waitlist(repeat('a',64),repeat('1',64)),'accepted','Cancelamento aceito');
select is((select count(*)::integer from public.waitlist where normalized_email='fase2-sql@example.invalid'),0,'E-mail eliminado');
select is((select count(*)::integer from public.consent_records where waitlist_id in (select id from consent_fixture)),0,'Consentimento eliminado em cascata');
insert into public.waitlist(normalized_email,unsubscribe_token_digest,created_at) values('fase2-expired@example.invalid',repeat('d',64),now()-interval '181 days');
select public.cleanup_waitlist();
select is((select count(*)::integer from public.waitlist where normalized_email='fase2-expired@example.invalid'),0,'Retenção de 180 dias executa');
select is((select count(*)::integer from cron.job where jobname='waitlist-retention'),1,'Limpeza diária agendada uma única vez');
select * from finish();
rollback;
